function QRAtasan(e){new QRCodeStyling({width:150,height:130,type:"canvas",imageOptions:{crossOrigin:"Anonymous",withCredentials:!1,quality:1,scale:4},data:e,image:"/asset/img/Lambang_KotaSingkawang.webp",dotsOptions:{color:"#000000",type:"rounded"}}).append(document.getElementById("qrcodeAtasan"))}function QRDirector(e){new QRCodeStyling({width:150,height:130,type:"svg",data:e,image:"/asset/img/Lambang_KotaSingkawang.webp",dotsOptions:{color:"#000000",type:"rounded"}}).append(document.getElementById("qrcodeDirector"))}function QRUser(e){new QRCodeStyling({width:150,height:130,type:"svg",data:e,image:"/asset/img/Lambang_KotaSingkawang.webp",dotsOptions:{color:"#000000",type:"rounded"}}).append(document.getElementById("qrcodeUser"))}let signature=getCookie("sigrnature");signature=decodeURIComponent(signature),$(document).ready(async function(){console.log("ready!"),QRAtasan(signature),QRUser(window.location.href),setTimeout(function(){window.print()},2500)});
